import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix='', env_mapping=os.environ):
    config = defaults.copy()

    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(toml_config)
        except FileNotFoundError:
            pass
        except tomllib.TOMLDecodeError as e:
            raise ConfigError(f'TOML decoding error: {e}')

    for key, value in env_mapping.items():
        if key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            config[env_key] = _coerce_value(value)

    return config

def _coerce_value(value):
    if value.isdigit():
        return int(value)
    elif value.lower() in ('true', 'yes', '1'):
        return True
    elif value.lower() in ('false', 'no', '0'):
        return False
    else:
        return value

import pytest
from envcfg import load_config, ConfigError

def test_load_defaults():
    defaults = {'a': 1, 'b': 'two'}
    config = load_config(defaults)
    assert config == {'a': 1, 'b': 'two'}

def test_load_toml():
    defaults = {'a': 1, 'b': 'two'}
    config = load_config(defaults, toml_path='config.toml')
    assert config == {'a': 1, 'b': 'two', 'c': 3}

def test_load_env():
    defaults = {'a': 1, 'b': 'two'}
    env_mapping = {'APP__A': '10', 'APP__B': 'three'}
    config = load_config(defaults, env_prefix='APP__', env_mapping=env_mapping)
    assert config == {'a': 10, 'b': 'three'}

def test_coerce_int():
    assert load_config({'a': 1}, env_mapping={'APP__A': '10'})['a'] == 10

def test_coerce_bool():
    assert load_config({'a': True}, env_mapping={'APP__A': 'false'})['a'] == False

def test_missing_toml():
    defaults = {'a': 1, 'b': 'two'}
    config = load_config(defaults, toml_path='missing.toml')
    assert config == {'a': 1, 'b': 'two'}

def test_toml_decoding_error():
    with pytest.raises(ConfigError) as excinfo:
        load_config({}, toml_path='invalid.toml')
    assert 'TOML decoding error' in str(excinfo.value)

def test_missing_env_key():
    defaults = {'a': 1, 'b': 'two'}
    env_mapping = {'APP__A': '10'}
    with pytest.raises(ConfigError) as excinfo:
        load_config(defaults, env_prefix='APP__', env_mapping=env_mapping)
    assert 'missing' in str(excinfo.value)
